package com.hrms.assignment.service;

import com.hrms.assignment.dto.*;import com.hrms.assignment.model.*;import com.hrms.assignment.repository.AssignmentRepository;import com.hrms.audit.service.AuditService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.exceptions.*;import com.hrms.employee.model.EmploymentStatus;import com.hrms.employee.repository.EmployeeRepository;import com.hrms.office.service.OfficeLocationService;import com.hrms.shift.service.ShiftService;import org.bson.types.ObjectId;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;import java.util.concurrent.ConcurrentHashMap;

@Service public class AssignmentService {
 private final AssignmentRepository assignments;private final EmployeeRepository employees;private final ShiftService shifts;private final OfficeLocationService offices;private final AuditService audit;private final ConcurrentHashMap<String,Object> locks=new ConcurrentHashMap<>();
 public AssignmentService(AssignmentRepository a,EmployeeRepository e,ShiftService s,OfficeLocationService o,AuditService audit){assignments=a;employees=e;shifts=s;offices=o;this.audit=audit;}
 @Transactional public AssignmentResponse create(String employeeId,CreateAssignmentRequest r,AuthPrincipal actor){validateEmployee(employeeId);if(r.effectiveTo()!=null&&r.effectiveTo().isBefore(r.effectiveFrom()))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"effectiveTo cannot be earlier than effectiveFrom");shifts.validateActive(r.shiftId());offices.validateActive(r.officeLocationId());synchronized(locks.computeIfAbsent(employeeId,k->new Object())){if(overlaps(employeeId,r.effectiveFrom(),r.effectiveTo(),null))throw new ConflictException("Assignment period overlaps an existing active assignment");EmployeeWorkAssignment a=new EmployeeWorkAssignment();a.setId(new ObjectId().toHexString());a.setEmployeeId(employeeId);a.setShiftId(r.shiftId());a.setOfficeLocationId(r.officeLocationId());a.setEffectiveFrom(r.effectiveFrom());a.setEffectiveTo(r.effectiveTo());a.setStatus(AssignmentStatus.ACTIVE);a.setCreatedBy(actor.userId());a.setReason(trim(r.reason()));assignments.save(a);audit.record(actor,"WORK_ASSIGNMENT_CREATED","EMPLOYEE_WORK_ASSIGNMENT",a.getId(),Map.of(),Map.of("employeeId",employeeId,"shiftId",r.shiftId(),"officeLocationId",r.officeLocationId()),r.reason());return AssignmentResponse.from(a);}}
 public List<AssignmentResponse> list(String employeeId){validateEmployee(employeeId);return assignments.findByEmployeeIdOrderByEffectiveFromDesc(employeeId).stream().map(AssignmentResponse::from).toList();}
 public AssignmentResponse get(String id){return AssignmentResponse.from(find(id));}
 @Transactional public AssignmentResponse end(String id,EndAssignmentRequest r,AuthPrincipal actor){EmployeeWorkAssignment a=find(id);if(a.getStatus()==AssignmentStatus.INACTIVE)return AssignmentResponse.from(a);if(r.effectiveTo().isBefore(a.getEffectiveFrom()))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"effectiveTo cannot be earlier than effectiveFrom");a.setEffectiveTo(r.effectiveTo());a.setStatus(AssignmentStatus.INACTIVE);assignments.save(a);audit.record(actor,"WORK_ASSIGNMENT_ENDED","EMPLOYEE_WORK_ASSIGNMENT",id,Map.of("status","ACTIVE"),Map.of("status","INACTIVE","effectiveTo",r.effectiveTo().toString()),r.reason());return AssignmentResponse.from(a);}
 public AssignmentResponse resolve(String employeeId,LocalDate date){validateEmployee(employeeId);return resolveStored(employeeId,date);}
 public AssignmentResponse resolveHistorical(String employeeId,LocalDate date){if(!ObjectId.isValid(employeeId)||employees.findById(employeeId).isEmpty())throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Employee id is invalid");return resolveStored(employeeId,date);}
 private AssignmentResponse resolveStored(String employeeId,LocalDate date){List<EmployeeWorkAssignment> matches=assignments.findByEmployeeIdOrderByEffectiveFromDesc(employeeId).stream().filter(a->!date.isBefore(a.getEffectiveFrom())&&(a.getEffectiveTo()==null||!date.isAfter(a.getEffectiveTo()))).toList();if(matches.size()!=1)throw new ApiException(ErrorCode.NO_WORK_ASSIGNMENT,org.springframework.http.HttpStatus.CONFLICT,matches.isEmpty()?"No assignment applies to "+date:"Multiple assignments apply to "+date);return AssignmentResponse.from(matches.getFirst());}
 private boolean overlaps(String employeeId,LocalDate from,LocalDate to,String excluded){return assignments.findByEmployeeIdAndStatus(employeeId,AssignmentStatus.ACTIVE).stream().filter(a->!a.getId().equals(excluded)).anyMatch(a->(to==null||!from.isAfter(a.getEffectiveTo()==null?LocalDate.MAX:a.getEffectiveTo()))&&(a.getEffectiveTo()==null||!to.isBefore(a.getEffectiveFrom())));}
 private void validateEmployee(String id){if(!ObjectId.isValid(id))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Employee id is invalid");employees.findById(id).filter(e->e.getEmploymentStatus()==EmploymentStatus.ACTIVE).orElseThrow(()->new ConflictException("Employee must exist and be active"));}private EmployeeWorkAssignment find(String id){if(!ObjectId.isValid(id))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Assignment id is invalid");return assignments.findById(id).orElseThrow(()->new ResourceNotFoundException("Work assignment was not found"));}private static String trim(String s){return s==null?null:s.strip();}
}
